/** 预设属于哪种 API，给人看的名字。 */
export function apiLabel(api: string): string {
  return ({ openai: '对话补全', textgenerationwebui: '文本补全', kobold: 'KoboldAI', novel: 'NovelAI' } as Record<string, string>)[api] ?? api;
}

export function presetApi(): string {
  try {
    return loaded.regexEngine?.getCurrentPresetAPI?.() ?? ctx().mainApi ?? '';
  } catch {
    return ctx().mainApi ?? '';
  }
}

export function currentPresetName(): string {
  try {
    return ctx().getPresetManager()?.getSelectedPresetName?.() ?? '';
  } catch {
    return '';
  }
}

export function presetNames(): string[] {
  try {
    return ctx().getPresetManager()?.getAllPresets?.() ?? [];
  } catch {
    return [];
  }
}

export function presetRegexCount(name: string): number {
  try {
    const p = ctx().getPresetManager()?.getCompletionPresetByName?.(name);
    return (p?.extensions?.regex_scripts ?? []).length;
  } catch {
    return 0;
  }
}

/** 卡的美化：和这张卡聊天时整个界面换成这套美化。null = 不指定。 */
export function setCardTheme(avatar: string, cardName: string, name: string | null): void {
  const s = settings();
  const p: EnvProfile = s.profiles[avatar] ?? { cardName };
  if (name) p.theme = name;
  else delete p.theme;
  p.cardName = cardName;
  p.updatedAt = new Date().toISOString();
  if (profileEmpty(p)) { delete s.profiles[avatar]; markDeleted('profiles', avatar); }
  else s.profiles[avatar] = p;
  saveSettings();
  bump();
}

export function setRecommendedPreset(avatar: string, cardName: string, name: string | null): void {
  const s = settings();
  const p: EnvProfile = s.profiles[avatar] ?? { cardName };
  if (name) p.preset = { api: presetApi(), name };
  else delete p.preset;
  p.cardName = cardName;
  p.updatedAt = new Date().toISOString();
  if (profileEmpty(p)) { delete s.profiles[avatar]; markDeleted('profiles', avatar); }
  else s.profiles[avatar] = p;
  saveSettings();
  refreshEnv();
  bump();
}

/** Switch to a preset by its exact name. /preset falls back to the closest-named preset, so check first. */
export async function switchPreset(name: string): Promise<boolean> {
  if (!presetNames().includes(name)) {
    toast('error', `没有换预设。找不到「${name}」，可能已经删除或改名了。`, '预设');
    return false;
  }
  await track('preset', () => runSlash(`/preset ${slashQuote(name)}`));
  refreshEnv();
  bump();
  return true;
}

// ------------------------------------------------------------ lorebooks ---

export async function checkWorld(info: CardInfo): Promise<BookDiff | null> {
  if (info.world.state !== 'ok' || info.world.embedded === null) return null;
  const f = findChar(info.avatar);
  const data = await loaded.worldInfo?.loadWorldInfo?.(info.world.name);
  if (!f || !data) return null;
  return diffBooks(cardBookEntries(f.char.data?.character_book), worldBookEntries(data));
}

function toBase64(text: string): string {
  const bytes = new TextEncoder().encode(text);
  let bin = '';
  for (let i = 0; i < bytes.length; i += 0x8000) bin += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
  return btoa(bin);
}

/** Save the current world file to data/<user>/user/files before it gets overwritten. */
async function backupWorld(name: string): Promise<string> {
  const data = await loaded.worldInfo?.loadWorldInfo?.(name);
  if (!data) throw new Error(`读不到世界书「${name}」`);
  const file = backupFileName(name, new Date());
  const res = await fetch('/api/files/upload', {
    method: 'POST',
    headers: ctx().getRequestHeaders(),
    body: JSON.stringify({ name: file, data: toBase64(JSON.stringify({ ...data, rbtBackupOf: name }, null, 2)) }),
  });
  if (!res.ok) throw new Error(`备份失败：${res.status} ${await res.text()}`);
  settings().worldBackups.push({ file, world: name, at: new Date().toISOString() });
  saveSettings();
  return file;
}

/** 世界书条目 → 卡里的 character_book 条目（和酒馆保存角色卡时 convertWorldInfoToCharacterBook 写的一样）。 */
function worldToCharacterBook(name: string, entries: Record<string, Any>): Any {
  return {
    name,
    entries: Object.values(entries).map((e: Any) => ({
      id: e.uid, keys: e.key, secondary_keys: e.keysecondary, comment: e.comment, content: e.content, constant: e.constant, selective: e.selective,
      insertion_order: e.order, enabled: !e.disable, position: e.position == 0 ? 'before_char' : 'after_char', use_regex: true,
      extensions: {
        ...e.extensions, position: e.position, exclude_recursion: e.excludeRecursion, display_index: e.displayIndex,
        probability: e.probability ?? null, useProbability: e.useProbability ?? false, depth: e.depth ?? 4, selectiveLogic: e.selectiveLogic ?? 0,
        outlet_name: e.outletName ?? '', group: e.group ?? '', group_override: e.groupOverride ?? false, group_weight: e.groupWeight ?? null,
        prevent_recursion: e.preventRecursion ?? false, delay_until_recursion: e.delayUntilRecursion ?? false, scan_depth: e.scanDepth ?? null,
        match_whole_words: e.matchWholeWords ?? null, use_group_scoring: e.useGroupScoring ?? false, case_sensitive: e.caseSensitive ?? null,
        automation_id: e.automationId ?? '', role: e.role ?? 0, vectorized: e.vectorized ?? false, sticky: e.sticky ?? null, cooldown: e.cooldown ?? null,
        delay: e.delay ?? null, match_persona_description: e.matchPersonaDescription ?? false, match_character_description: e.matchCharacterDescription ?? false,
        match_character_personality: e.matchCharacterPersonality ?? false, match_character_depth_prompt: e.matchCharacterDepthPrompt ?? false,
        match_scenario: e.matchScenario ?? false, match_creator_notes: e.matchCreatorNotes ?? false, triggers: e.triggers ?? [], ignore_budget: e.ignoreBudget ?? false,
      },
    })),
  };
}

/**
 * 「用现在的更新卡里的」：把绑定的世界书写回卡里自带的那份（之后导出、分享这张卡带的就是它）。
 * 写之前把卡里原来那份存一个备份文件。
 */
export async function updateCardBook(avatar: string): Promise<boolean> {
  const f = findChar(avatar);
  const name: string = f?.char?.data?.extensions?.world ?? '';
  const data = name ? await loaded.worldInfo?.loadWorldInfo?.(name) : null;
  if (!f || !data?.entries) { toast('error', name ? `卡里的世界书没有更新，因为读不到世界书「${name}」。` : '卡里的世界书没有更新，因为这张卡没有绑世界书。'); return false; }
  try {
    const old = f.char.data?.character_book;
    if (old) {
      const file = backupFileName(`${name}（卡里原来的）`, new Date());
      const res = await fetch('/api/files/upload', { method: 'POST', headers: ctx().getRequestHeaders(), body: JSON.stringify({ name: file, data: toBase64(JSON.stringify({ character_book: old, rbtBackupOf: avatar }, null, 2)) }) });
      if (!res.ok) throw new Error(`备份失败：${res.status}`);
      settings().worldBackups.push({ file, world: name, at: new Date().toISOString() });
      saveSettings();
    }
    const book = worldToCharacterBook(name, data.entries);
    const res = await fetch('/api/characters/merge-attributes', { method: 'POST', headers: ctx().getRequestHeaders(), body: JSON.stringify({ avatar, data: { character_book: book } }) });
    if (!res.ok) throw new Error(`${res.status} ${await res.text()}`);
    if (f.char.data) f.char.data.character_book = book;
    toast('success', '已更新卡里的世界书。原来的版本已备份。');
    bump();
    return true;
  } catch (e) {
    toast('error', `没能更新「${f.char.name}」卡里的世界书。请再试一次。（${String((e as Error)?.message ?? e)}）`);
    return false;
  }
}

/**
 * 把一本世界书设成这张卡自己的（酒馆的「主要世界书」），并写进卡里，之后导出、分享这张卡会带上它。
 * 和在酒馆角色编辑里「链接到世界书」选「主要世界书」一样。只在这张卡还没有自己的世界书时用。
 */
export async function bindCardWorld(avatar: string, name: string): Promise<boolean> {
  await ensureFullCharacter(avatar);
  const f = findChar(avatar);
  const data = await loaded.worldInfo?.loadWorldInfo?.(name);
  if (!f || !data?.entries) { toast('error', `没能绑定世界书「${name}」，因为读不到它。请刷新后再试。`, '角色档案'); return false; }
  try {
    await ctx().writeExtensionField(f.chid, 'world', name);
    const book = worldToCharacterBook(name, data.entries);
    const res = await fetch('/api/characters/merge-attributes', { method: 'POST', headers: ctx().getRequestHeaders(), body: JSON.stringify({ avatar, data: { character_book: book } }) });
    if (!res.ok) throw new Error(`${res.status} ${await res.text()}`);
    if (f.char.data) f.char.data.character_book = book;
    skipWorldPrompt(avatar);
    toast('success', `已把世界书「${name}」绑定给「${f.char.name}」。`, '角色档案');
    refreshEnv();
    bump();
    return true;
  } catch (e) {
    toast('error', `没能把世界书「${name}」绑定给「${f.char.name}」。请再试一次。（${String((e as Error)?.message ?? e)}）`, '角色档案');
    return false;
  }
}

/** 酒馆打开带世界书的卡时，每张卡会弹一次英文的「要不要导入」。工具箱自己导入时，让它别再问。 */
export function skipWorldPrompt(avatar: string): void {
  try { ctx().accountStorage?.setItem(`AlertWI_${avatar}`, 'true'); } catch { /* ignore */ }
}

export type ImportResult = 'imported' | 'overwritten' | 'exists' | 'nobook' | 'failed';

/**
 * Import the card's embedded lorebook (same as ST's "导入卡内世界书"), binding it to the card if needed.
 * Never overwrites an existing world file unless `overwrite` is set, and then backs it up first.
 */
export async function importCardWorld(avatar: string, { overwrite = false, quiet = false } = {}): Promise<ImportResult> {
  // 懒加载时没打开过的卡读不到世界书，先把整张卡读回来
  await ensureFullCharacter(avatar);
  const f = findChar(avatar);
  const wi = loaded.worldInfo;
  const book = f?.char?.data?.character_book;
  if (!f || !wi || !book?.entries?.length) return 'nobook';
  const info = cardInfo(f.char);
  const name = info.world.importName;
  const exists = worldNames().includes(name);
  if (exists && !overwrite) return 'exists';
  try {
    let backup = '';
    if (exists) backup = await backupWorld(name);
    await wi.saveWorldInfo(name, wi.convertCharacterBook(structuredClone(book)), true);
    await wi.updateWorldInfoList();
    if (f.char.data?.extensions?.world !== name) await ctx().writeExtensionField(f.chid, 'world', name);
    skipWorldPrompt(avatar);
    if (!quiet) {
      toast('success', exists
        ? `已用卡里的世界书替换「${name}」。原来的版本已备份。`
        : `已从卡里导入世界书「${name}」，并绑定到「${f.char.name}」。`, '角色档案');
    }
    refreshEnv();
    bump();
    return exists ? 'overwritten' : 'imported';
  } catch (e) {
    console.error('[RedBird] world import failed', e);
    toast('error', `没能导入世界书「${name}」。请再试一次。（${(e as Error).message}）`, '角色档案');
    return 'failed';
  }
}

/** Cards whose embedded lorebook could be imported without overwriting anything. */
export function cardsMissingWorld(): CardInfo[] {
  const names = worldNames();
  return allCharacters().map(cardInfo).filter((i) => i.world.embedded && (i.world.state === 'missing' || (i.world.state === 'unbound' && !names.includes(i.world.importName))));
}

export async function importAllMissingWorlds(): Promise<number> {
  let n = 0;
  for (const i of cardsMissingWorld()) if ((await importCardWorld(i.avatar, { quiet: true })) === 'imported') n++;
  toast('success', `已从卡里导入 ${n} 本世界书。`, '角色档案');
  return n;
}

// ----------------------------------------------------------- regex owners ---

export function globalRegexScripts(): Any[] {
  return ctx().extensionSettings?.regex ?? [];
}

/**
 * 把全局正则移进一张卡或一个预设（酒馆自己的「卡里的正则」「预设里的正则」，只在那张卡 / 那个预设里运行）。
 * 酒馆自带的「移动」只能移到正在聊的卡和正在用的预设，这里哪个都行。移过去的正则打开，
 * 顺手允许那张卡 / 那个预设的正则运行，再从全局删掉。弹一条通知，点一下全部移回全局。
 */
type MoveTo = RegexOwner & { kind: 'card' | 'preset' };

/** 那张卡 / 那个预设现在的正则；卡或预设找不到时是 null。 */
async function targetRegex(to: MoveTo): Promise<Any[] | null> {
  if (to.kind === 'card') {
    await ensureFullCharacter(to.key);
    const f = findChar(to.key);
    return f && !f.char.shallow ? [...(f.char.data?.extensions?.regex_scripts ?? [])] : null;
  }
  if (!presetNames().includes(to.key)) return null;
  const v = ctx().getPresetManager()?.readPresetExtensionField?.({ name: to.key, path: 'regex_scripts' });
  return Array.isArray(v) ? [...v] : [];
}

async function writeTargetRegex(to: MoveTo, list: Any[]): Promise<void> {
  if (to.kind === 'card') await ctx().writeExtensionField(findChar(to.key)!.chid, 'regex_scripts', list);
  else await ctx().getPresetManager().writePresetExtensionField({ name: to.key, path: 'regex_scripts', value: list });
}

function targetAllowed(to: MoveTo): boolean {
  const es = ctx().extensionSettings ?? {};
  return to.kind === 'card' ? (es.character_allowed_regex ?? []).includes(to.key) : (es.preset_allowed_regex?.[presetApi()] ?? []).includes(to.key);
}

function allowTarget(to: MoveTo, on: boolean): void {
  const re = loaded.regexEngine;
  if (to.kind === 'card') { const c = findChar(to.key)?.char; if (on) re.allowScopedScripts(c); else re.disallowScopedScripts(c); }
  else if (on) re.allowPresetScripts(presetApi(), to.key);
  else re.disallowPresetScripts(presetApi(), to.key);
}

/**
 * 以前的版本可以给全局正则选「属于」哪张卡 / 哪个预设，换卡时自动开关。现在去掉了：
 * 刷新页面后把它们移进选好的卡 / 预设（卡、预设或正则不在了的只删记录），记录都删掉。
 * 要在角色列表载入后调用（不然卡都找不到，记录会被当成没用的删掉）。
 */
export async function migrateRegexOwners(): Promise<void> {
  const s = settings();
  const ids = Object.keys(s.regexOwners);
  if (!ids.length) return;
  const presets = presetNames();
  const global = new Set(globalRegexScripts().map((r) => String(r.id)));
  const moves: { id: string; to: MoveTo }[] = [];
  for (const id of ids) {
    const o = s.regexOwners[id];
    if (global.has(id) && ((o.kind === 'card' && findChar(o.key)) || (o.kind === 'preset' && presets.includes(o.key)))) moves.push({ id, to: o as MoveTo });
    else { delete s.regexOwners[id]; markDeleted('regexOwners', id); }
  }
  saveSettings();
  if (moves.length) await moveRegex(moves, (n) => `以前选了「属于」的 ${n} 条正则，已移进选好的卡和预设里。`);
}

export async function moveRegex(moves: { id: string; to: MoveTo }[], message?: (n: number) => string): Promise<void> {
  const GLOBAL = 0;
  const re = loaded.regexEngine;
  const global: Any[] = re?.getScriptsByType?.(GLOBAL) ?? [];
  const groups = new Map<string, { to: MoveTo; scripts: Any[] }>();
  for (const m of moves) {
    const s = global.find((x) => x.id === m.id);
    if (!s) continue;
    const k = `${m.to.kind}:${m.to.key}`;
    if (!groups.has(k)) groups.set(k, { to: m.to, scripts: [] });
    groups.get(k)!.scripts.push({ ...structuredClone(s), disabled: false });
  }
  const done: { to: MoveTo; ids: string[]; wasAllowed: boolean }[] = [];
  for (const { to, scripts } of groups.values()) {
    try {
      const cur = await targetRegex(to);
      if (!cur) continue;
      const ids = scripts.map((s) => s.id);
      await writeTargetRegex(to, [...cur.filter((s) => !ids.includes(s.id)), ...scripts]);
      const wasAllowed = targetAllowed(to);
      if (!wasAllowed) allowTarget(to, true);
      done.push({ to, ids, wasAllowed });
    } catch (e) {
      console.error('[RedBird] regex move failed', to, e);
    }
  }
  const moved = new Set(done.flatMap((d) => d.ids));
  if (!moved.size) { toast('error', '没能移过去。请刷新页面再试一次。'); return; }
  const removed = global.map((s, index) => ({ s, index })).filter((x) => moved.has(x.s.id));
  await re.saveScriptsByType(global.filter((s) => !moved.has(s.id)), GLOBAL);
  const s = settings();
  for (const id of moved) if (s.regexOwners[id]) { delete s.regexOwners[id]; markDeleted('regexOwners', id); }
  const after = () => { saveSettings(); refreshEnv(); bump(); void reloadChatSafe(); };
  after();

  const undo = async () => {
    for (const d of done) {
      const cur = await targetRegex(d.to);
      if (cur) await writeTargetRegex(d.to, cur.filter((x) => !d.ids.includes(x.id)));
      if (!d.wasAllowed) allowTarget(d.to, false);
    }
    const list: Any[] = [...(re.getScriptsByType(GLOBAL) ?? [])];
    for (const r of removed) if (!list.some((x) => x.id === r.s.id)) list.splice(Math.min(r.index, list.length), 0, r.s);
    await re.saveScriptsByType(list, GLOBAL);
    after();
    toast('success', '已移回全局。');
  };
  const failed = moves.length - moved.size;
  const what = message ? message(removed.length) : removed.length === 1 ? `已把「${removed[0].s.scriptName || '(未命名正则)'}」移到「${done[0].to.label}」里。` : `已把 ${removed.length} 条正则移到各自的卡和预设里。`;
  let undone = false;
  toast(failed ? 'warning' : 'success', `${what}${failed ? `另有 ${failed} 条没移成，请再试一次。` : ''}点这里撤销。`, APP_NAME, {
    timeOut: 15000,
    extendedTimeOut: 8000,
    onclick: () => { if (!undone) { undone = true; void undo(); } },
  });
}

// --------------------------------------------------------------- overview ---

export interface Overview {
  cards: CardInfo[];
  byPreset: Map<string, CardInfo[]>;
  byWorld: Map<string, CardInfo[]>;
  /** 卡的美化：美化名 → 用它的卡 */
  byTheme: Map<string, CardInfo[]>;
  unusedWorlds: { name: string; global: boolean }[];
  orphans: OrphanRecord[];
}

export function buildOverview(): Overview {
  const chars = allCharacters();
  const cards = chars.map(cardInfo).sort((a, b) => a.name.localeCompare(b.name, 'zh'));
  const byPreset = new Map<string, CardInfo[]>();
  const byWorld = new Map<string, CardInfo[]>();
  const byTheme = new Map<string, CardInfo[]>();
  const profiles = settings().profiles;
  for (const c of cards) {
    const t = profiles[c.avatar]?.theme;
    if (t) byTheme.set(t, [...(byTheme.get(t) ?? []), c]);
    if (c.preset) byPreset.set(c.preset.name, [...(byPreset.get(c.preset.name) ?? []), c]);
    for (const w of [c.world.name, ...c.world.extra].filter(Boolean)) byWorld.set(w, [...(byWorld.get(w) ?? []), c]);
  }
  const selected: string[] = loaded.worldInfo?.selected_world_info ?? [];
  const unusedWorlds = worldNames().filter((w) => !byWorld.has(w)).map((name) => ({ name, global: selected.includes(name) }));
  const s = settings();
  const recordKeys: Record<string, { cardName: string }> = {};
  for (const [k, v] of Object.entries(s.cards)) recordKeys[k] = v;
  for (const [k, v] of Object.entries(s.profiles)) recordKeys[k] ??= v;
  const orphans = findOrphans(recordKeys, chars.map((c) => ({ avatar: c.avatar, name: c.name })));
  return { cards, byPreset, byWorld, byTheme, unusedWorlds, orphans };
}

/** Move a record (and profile) from an old avatar to a new one. */
export function relink(oldAvatar: string, newAvatar: string): void {
  const s = settings();
  const f = findChar(newAvatar);
  if (s.cards[oldAvatar]) { s.cards[newAvatar] = { ...s.cards[oldAvatar], cardName: f?.char?.name ?? s.cards[oldAvatar].cardName }; delete s.cards[oldAvatar]; markDeleted('cards', oldAvatar); s.cards[newAvatar].updatedAt = new Date().toISOString(); }
  if (s.profiles[oldAvatar]) { s.profiles[newAvatar] = { ...s.profiles[oldAvatar], updatedAt: new Date().toISOString() }; delete s.profiles[oldAvatar]; markDeleted('profiles', oldAvatar); }
  saveSettings();
  refreshEnv();
  bump();
}

export function dropRecord(avatar: string): void {
  const s = settings();
  delete s.cards[avatar];
  delete s.profiles[avatar];
  markDeleted('cards', avatar);
  markDeleted('profiles', avatar);
  saveSettings();
  refreshEnv();
  bump();
}

// ---------------------------------------------------------- export/import ---

export function exportArchive(): void {
  const s = settings();
  const file: ArchiveFile = {
    format: ARCHIVE_FORMAT, version: 1, exportedAt: new Date().toISOString(),
    cards: s.cards, profiles: s.profiles, regexOwners: s.regexOwners,
    presetInfo: s.presetInfo, pluginInfo: s.pluginInfo, worldSources: s.worldSources, themeInfo: s.themeInfo,
  };
  const blob = new Blob([JSON.stringify(file, null, 2)], { type: 'application/json' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = `RedBird-角色档案-${new Date().toISOString().slice(0, 10)}.json`;
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(a.href), 1000);
}

export async function importArchive(text: string, mode: 'merge' | 'overwrite'): Promise<void> {
  const inc = parseArchive(text);
  const s = settings();
  if (mode === 'overwrite') {
    const ok = await confirmText('用文件里的档案替换现在的？', '现在所有的角色档案、记住的配套、正则归属，以及预设、世界书、插件和美化的来源，都会换成文件里的。现在的会被替换，不能撤销。想留一份的话，先点「导出」。', '覆盖');
    if (!ok) return;
  }
  s.cards = mergeRecords(s.cards, inc.cards, mode, (v) => v.updatedAt ?? '');
  s.profiles = mergeRecords(s.profiles, inc.profiles as Record<string, EnvProfile>, mode, (v) => v.updatedAt ?? v.savedAt ?? '');
  s.regexOwners = mergeRecords(s.regexOwners, inc.regexOwners, mode);
  s.presetInfo = mergeRecords(s.presetInfo, inc.presetInfo ?? {}, mode, (v) => v.updatedAt ?? '');
  s.pluginInfo = mergeRecords(s.pluginInfo, inc.pluginInfo ?? {}, mode, (v) => v.updatedAt ?? '');
  s.worldSources = mergeRecords(s.worldSources, inc.worldSources ?? {}, mode, (v) => v.updatedAt ?? '');
  s.themeInfo = mergeRecords(s.themeInfo, inc.themeInfo ?? {}, mode, (v) => v.updatedAt ?? '');
  saveSettings();
  // 覆盖导入：文件里的就是全部，直接写进工具箱自己的存档，不和旧的合并
  if (mode === 'overwrite') { s.deleted = {}; void syncStore(true); }
  refreshEnv();
  bump();
  toast('success', `已导入 ${Object.keys(inc.cards).length} 张卡的档案（${mode === 'merge' ? '合并' : '覆盖'}）。`, '角色档案');
}

// ---------------------------------------------------------------- watch ---

let lastAvatar: string | null = null;

export function installCardsWatch(): void {
  const c = ctx();
  c.eventSource.on(c.eventTypes.CHAT_CHANGED, () => {
    archiveTarget.value = null;
    bump();
    // 换卡时导入卡里的世界书、提示插件，由 autoapply.ts 做
    lastAvatar = String(currentCharacter()?.avatar ?? '') || null;
  });
  for (const ev of [c.eventTypes.SETTINGS_UPDATED, c.eventTypes.WORLDINFO_SETTINGS_UPDATED, c.eventTypes.OAI_PRESET_CHANGED_AFTER, c.eventTypes.CHARACTER_EDITED]) {
    if (ev) c.eventSource.on(ev, bump);
  }
  // 在酒馆里改卡名，卡的文件名（avatar）也会跟着改：把档案、绑定、正则归属搬到新名字上，不然全部悄悄脱钩
  if (c.eventTypes.CHARACTER_RENAMED) {
    c.eventSource.on(c.eventTypes.CHARACTER_RENAMED, (oldAvatar: unknown, newAvatar: unknown) => {
      if (typeof oldAvatar !== 'string' || typeof newAvatar !== 'string' || !oldAvatar || oldAvatar === newAvatar) return;
      if (lastAvatar === oldAvatar) lastAvatar = newAvatar;
      relink(oldAvatar, newAvatar);
    });
  }
}
